import { useEffect, useState } from "react";
import { Button, Card, PageLede } from "@augmatic/ui";
import { api } from "../../lib/api";

const CALLS = [
  ["repair", "Repair"],
  ["ghost", "Ghosts"],
  ["recycle", "Recycle"],
  ["refresh", "Refresh"],
  ["redeploy", "Redeploy"],
  ["keep", "Keep"],
] as const;

export function AnalyzeView() {
  const [biz, setBiz] = useState<any[]>([]);
  const [summaries, setSummaries] = useState<Record<string, any>>({});

  useEffect(() => {
    (async () => {
      const b = await api("/api/partner/businesses");
      const list = b.businesses || [];
      setBiz(list);
      const entries = await Promise.all(
        list.map(async (row: any) => {
          try {
            const s = await api(`/api/summary?tenant=${encodeURIComponent(row.business_id)}`);
            return [row.business_id, s] as const;
          } catch {
            return [row.business_id, null] as const;
          }
        })
      );
      setSummaries(Object.fromEntries(entries));
    })().catch(() => undefined);
  }, []);

  if (!biz.length) {
    return <PageLede>Add a business first, then open its report here.</PageLede>;
  }

  return (
    <div className="space-y-4">
      <PageLede>Pick a business, then open its report or a call filter.</PageLede>
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {biz.map((b) => {
          const tid = encodeURIComponent(b.business_id);
          const base = `/app/?from=partner&tenant=${tid}`;
          const s = summaries[b.business_id];
          return (
            <Card key={b.business_id}>
              <h3 className="mb-3 text-base font-semibold tracking-tight">{b.business_name}</h3>
              <div className="mb-4 grid grid-cols-2 gap-2 text-sm">
                <div>
                  <div className="text-xs text-muted">Devices</div>
                  <div className="font-semibold">{s?.deviceCount ?? "…"}</div>
                </div>
                <div>
                  <div className="text-xs text-muted">
                    Avg GLOW<sup className="glow-tm">™</sup>
                  </div>
                  <div className="font-semibold">{s?.avgGlowScore ?? "…"}</div>
                </div>
              </div>
              <div className="mb-3 flex flex-wrap gap-2">
                <Button asChild size="sm">
                  <a href={`${base}&view=fleet`}>Fleet report</a>
                </Button>
                <Button asChild variant="ghost" size="sm">
                  <a href={`${base}&view=dashboard`}>Dashboard</a>
                </Button>
              </div>
              <div className="flex flex-wrap gap-1.5">
                {CALLS.map(([id, label]) => (
                  <a
                    key={id}
                    className="rounded-full bg-surface px-2.5 py-1 text-xs font-medium text-ink-2 hover:bg-white"
                    href={`${base}&view=fleet&call=${id}`}
                  >
                    {label}
                  </a>
                ))}
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
