import { Badge } from "../components/badge";

const CALLS = ["keep", "repair", "redeploy", "refresh", "recycle", "ghost"] as const;
export type CallKind = (typeof CALLS)[number];

export function callLabel(raw: string | null | undefined) {
  const call = String(raw || "keep").toLowerCase();
  return call.charAt(0).toUpperCase() + call.slice(1);
}

export function CallPill({ call }: { call: string | null | undefined }) {
  const kind = String(call || "keep").toLowerCase() as CallKind;
  const variant = CALLS.includes(kind) ? kind : "default";
  return <Badge variant={variant as any}>{callLabel(kind)}</Badge>;
}
