import { useSearchParams } from "react-router-dom";
import { Button, CallPill, Card, EmptyState } from "@augmatic/ui";
import { useFleet } from "../fleet-context";

export function PropertiesView() {
  const { devices } = useFleet();
  const [params, setParams] = useSearchParams();
  const id = params.get("device");
  const d = devices.find((x) => String(x.id) === String(id)) || null;

  function backFleet() {
    const p = new URLSearchParams(params);
    p.delete("view");
    p.delete("device");
    setParams(p);
  }

  if (!d) {
    return (
      <EmptyState
        title="Properties"
        description="Pick a device from Fleet to see its full property set."
        action={
          <Button variant="ghost" onClick={backFleet}>
            ← Fleet
          </Button>
        }
      />
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="sm" onClick={backFleet}>
          ← Fleet
        </Button>
      </div>
      <h1 className="text-xl font-semibold tracking-tight">{d.device_name || d.id}</h1>
      <p className="font-mono text-xs text-muted">{d.serial_number || "no serial"}</p>
      <div className="grid gap-4 md:grid-cols-2">
        <Card>
          <div className="space-y-2 text-sm">
            <div className="flex justify-between">
              <span className="text-muted">Call</span>
              <CallPill call={d.call_label || d.call} />
            </div>
            <div className="flex justify-between">
              <span className="text-muted">
                GLOW<sup className="glow-tm">™</sup>
              </span>
              <strong>{d.glow_score ?? "—"}</strong>
            </div>
            <div className="flex justify-between">
              <span className="text-muted">Battery</span>
              <strong>{d.battery_health != null ? `${d.battery_health}%` : "—"}</strong>
            </div>
            <div className="flex justify-between">
              <span className="text-muted">Compliance</span>
              <strong>{d.compliance_state || "—"}</strong>
            </div>
            <div className="flex justify-between">
              <span className="text-muted">User</span>
              <strong>{d.user_display_name || "—"}</strong>
            </div>
          </div>
        </Card>
        <Card>
          <h3 className="mb-2 text-sm font-semibold">Why</h3>
          <p className="text-sm text-muted">{d.rationale || d.health_notes || "—"}</p>
        </Card>
      </div>
    </div>
  );
}
