import { useMemo } from "react";
import {
  Button,
  CallPill,
  EmptyState,
  Input,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@augmatic/ui";
import { useFleet } from "../fleet-context";

const CALLS = ["all", "keep", "repair", "redeploy", "refresh", "recycle", "ghost"];

export function FleetView({ onSelectDevice }: { onSelectDevice: (id: string) => void }) {
  const {
    devices,
    summary,
    loading,
    error,
    selectedId,
    setSelectedId,
    activeCall,
    setActiveCall,
    search,
    setSearch,
    tenant,
  } = useFleet();

  const by = summary?.byCall || {};
  const total = summary?.deviceCount ?? devices.length;

  const filtered = useMemo(() => {
    let list = [...devices];
    if (activeCall !== "all") {
      list = list.filter(
        (d) => String(d.call_label || d.call || "keep").toLowerCase() === activeCall
      );
    }
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter((d) =>
        [d.device_name, d.serial_number, d.model, d.user_display_name]
          .filter(Boolean)
          .join(" ")
          .toLowerCase()
          .includes(q)
      );
    }
    return list;
  }, [devices, activeCall, search]);

  const selected =
    filtered.find((d) => String(d.id) === String(selectedId)) || filtered[0] || null;

  return (
    <div className="grid h-full min-h-0 gap-3.5 lg:grid-cols-[232px_minmax(0,1fr)_300px]">
      <aside className="flex min-h-0 flex-col overflow-auto rounded-2xl bg-surface shadow-[var(--shadow-soft)]">
        <p className="flex items-center gap-2 border-b border-line px-4 py-3 text-xs font-medium text-muted">
          <span className="h-1.5 w-1.5 rounded-full bg-teal shadow-[0_0_0_3px_var(--color-teal-bg)]" />
          {loading ? "Loading…" : error ? error : `${total} scored`}
        </p>
        <div className="grid grid-cols-2 gap-1.5 p-3">
          {[
            [summary?.deviceCount ?? 0, "Devices"],
            [summary?.avgGlowScore ?? "—", "Avg GLOW™"],
            [summary?.ghostCount ?? 0, "Ghosts"],
            [summary?.repairBeforeReplaceCount ?? 0, "Repair"],
            [summary?.manufacturingKgOnBooks ?? 0, "Mfg kg"],
            [summary?.avoidablePurchasesIfExtended ?? 0, "Avoid"],
          ].map(([v, l]) => (
            <div key={String(l)} className="rounded-lg bg-surface-2 px-3 py-2.5">
              <div className="text-xl font-semibold tabular-nums tracking-tight">{v}</div>
              <div className="text-[0.7rem] font-medium text-muted">{l}</div>
            </div>
          ))}
        </div>
        <div className="flex flex-1 flex-col gap-1 px-3 pb-2">
          {CALLS.map((c) => {
            const count = c === "all" ? total : by[c] || 0;
            const label = c === "all" ? "All" : c.charAt(0).toUpperCase() + c.slice(1);
            const on = activeCall === c;
            return (
              <button
                key={c}
                type="button"
                onClick={() => setActiveCall(c)}
                className={`flex h-8.5 items-center justify-between rounded-full px-3 text-xs font-medium ${
                  on ? "bg-accent text-accent-ink" : "bg-surface-2 text-ink-2 hover:bg-[#e9ede3]"
                }`}
              >
                <span>{label}</span>
                <b className="font-mono tabular-nums">{count}</b>
              </button>
            );
          })}
        </div>
        <div className="p-3">
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search…"
          />
        </div>
      </aside>

      <section className="flex min-h-0 flex-col overflow-hidden rounded-2xl bg-surface shadow-[var(--shadow-soft)]">
        <div className="flex items-center justify-between gap-3 border-b border-line px-4 py-3">
          <h1 className="text-lg font-semibold tracking-tight">Fleet report</h1>
          <div className="flex gap-2">
            <Button variant="ghost" size="sm">
              Print PDF
            </Button>
            <Button variant="ghost" size="sm">
              Send
            </Button>
          </div>
        </div>
        <div className="min-h-0 flex-1 overflow-auto">
          {filtered.length === 0 ? (
            <div className="p-6">
              {devices.length === 0 ? (
                <EmptyState
                  title="No devices yet"
                  description={
                    <>
                      Add devices for <strong>{summary?.businessName || "this business"}</strong>.
                    </>
                  }
                  action={
                    <div className="flex flex-wrap gap-2">
                      <Button asChild variant="secondary" size="sm">
                        <a href="/partner/?view=resources">Intune / Entra</a>
                      </Button>
                      <Button asChild size="sm">
                        <a href={`/partner/enroll`}>Enroll agent</a>
                      </Button>
                      <Button asChild variant="ghost" size="sm">
                        <a href="/download/GlowOpsAgent-Win32.zip">Win32 pack</a>
                      </Button>
                    </div>
                  }
                />
              ) : (
                <EmptyState title="No devices match this filter." />
              )}
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Device</TableHead>
                  <TableHead>Call</TableHead>
                  <TableHead>
                    GLOW<sup className="glow-tm">™</sup>
                  </TableHead>
                  <TableHead>Age</TableHead>
                  <TableHead>Sync</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((d) => {
                  const id = String(d.id);
                  const sel = id === String(selected?.id);
                  return (
                    <TableRow
                      key={id}
                      data-selected={sel}
                      onClick={() => setSelectedId(id)}
                      className="cursor-pointer"
                    >
                      <TableCell>
                        <div className="font-semibold">{d.device_name || "—"}</div>
                        <div className="font-mono text-[0.7rem] text-muted">
                          {d.serial_number || ""}
                        </div>
                      </TableCell>
                      <TableCell>
                        <CallPill call={d.call_label || d.call} />
                      </TableCell>
                      <TableCell className="tabular-nums">{d.glow_score ?? "—"}</TableCell>
                      <TableCell>{d.age_years != null ? `${d.age_years}y` : "—"}</TableCell>
                      <TableCell>
                        {d.check_in_days != null ? `${d.check_in_days}d` : "—"}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          )}
        </div>
      </section>

      <aside className="flex min-h-0 flex-col overflow-auto rounded-2xl bg-surface p-4 shadow-[var(--shadow-soft)]">
        <p className="mb-3 text-xs font-medium text-muted">Selected device</p>
        {!selected ? (
          <p className="text-sm text-muted">Pick a device from the list</p>
        ) : (
          <>
            <h2 className="text-lg font-semibold tracking-tight">{selected.device_name || "—"}</h2>
            <p className="mb-1 font-mono text-xs text-muted">{selected.serial_number || "no serial"}</p>
            <p className="mb-4 text-sm text-ink-2">
              {[selected.manufacturer, selected.model].filter(Boolean).join(" ") || "—"}
            </p>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between gap-3 border-b border-line py-2">
                <span className="text-muted">Call</span>
                <CallPill call={selected.call_label || selected.call} />
              </div>
              <div className="flex justify-between gap-3 border-b border-line py-2">
                <span className="text-muted">
                  GLOW<sup className="glow-tm">™</sup>
                </span>
                <strong className="tabular-nums">{selected.glow_score ?? "—"}</strong>
              </div>
              <div className="flex justify-between gap-3 border-b border-line py-2">
                <span className="text-muted">Battery</span>
                <strong>
                  {selected.battery_health != null ? `${selected.battery_health}%` : "—"}
                </strong>
              </div>
              <div className="flex justify-between gap-3 border-b border-line py-2">
                <span className="text-muted">Compliance</span>
                <strong>{selected.compliance_state || "—"}</strong>
              </div>
              <div className="flex justify-between gap-3 border-b border-line py-2">
                <span className="text-muted">User</span>
                <strong>{selected.user_display_name || "—"}</strong>
              </div>
            </div>
            <p className="mt-3 text-sm text-muted">{selected.rationale || selected.health_notes || ""}</p>
            <Button className="mt-4" onClick={() => onSelectDevice(String(selected.id))}>
              Properties
            </Button>
          </>
        )}
        {!tenant ? null : null}
      </aside>
    </div>
  );
}
