import { useEffect, useMemo, useState } from "react";
import { Navigate, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import {
  AppShell,
  Button,
  SideNav,
  Wordmark,
} from "@augmatic/ui";
import { useAppAuth, UserButton } from "../lib/auth";
import { api } from "../lib/api";
import { HomeView } from "./views/HomeView";
import { EnrollView } from "./views/EnrollView";
import { BusinessesView } from "./views/BusinessesView";
import { PeopleView } from "./views/PeopleView";
import { AnalyzeView } from "./views/AnalyzeView";
import { ResourcesView } from "./views/ResourcesView";
import { SettingsView } from "./views/SettingsView";

const NAV = [
  { id: "home", label: "Home" },
  { id: "enroll", label: "Enroll" },
  { id: "biz", label: "Businesses" },
  { id: "people", label: "People" },
  { id: "analyze", label: "Analyze" },
  { id: "resources", label: "Resources" },
  { id: "settings", label: "Settings" },
];

export function PartnerApp() {
  const { ready, signedIn, displayName, refreshToken } = useAppAuth();
  const nav = useNavigate();
  const loc = useLocation();
  const [bizCount, setBizCount] = useState<string | number>("—");
  const [keyCount, setKeyCount] = useState<string | number>("—");

  const active = useMemo(() => {
    const part = loc.pathname.replace(/^\/partner\/?/, "") || "home";
    const id = part.split("/")[0] || "home";
    return NAV.some((n) => n.id === id) ? id : "home";
  }, [loc.pathname]);

  useEffect(() => {
    if (!ready) return;
    if (!signedIn) {
      const next = encodeURIComponent(loc.pathname + loc.search);
      nav(`/partner/sign-in?next=${next}`, { replace: true });
    }
  }, [ready, signedIn, loc.pathname, loc.search, nav]);

  useEffect(() => {
    if (!signedIn) return;
    void (async () => {
      await refreshToken();
      try {
        const me = await api("/api/partner/me");
        setBizCount(me.businessCount ?? me.businesses?.length ?? "—");
      } catch {
        /* ignore */
      }
      try {
        const keys = await api("/api/partner/mcp-keys");
        setKeyCount(Array.isArray(keys.keys) ? keys.keys.length : keys.length ?? "—");
      } catch {
        /* ignore */
      }
    })();
  }, [signedIn, refreshToken]);

  if (!ready || !signedIn) {
    return (
      <div className="grid h-dvh place-items-center bg-canvas">
        <div className="text-center">
          <div className="mx-auto mb-3 h-3.5 w-3.5 rounded-full bg-accent shadow-[0_0_14px_3px_rgba(191,247,71,0.65)]" />
          <p className="text-2xl font-semibold tracking-tight">Welcome to GLOW Ops.</p>
        </div>
      </div>
    );
  }

  return (
    <AppShell
      sidebar={
        <SideNav
          brand={<Wordmark />}
          kicker="Partner level"
          items={NAV}
          activeId={active}
          onSelect={(id) => nav(id === "home" ? "/partner/" : `/partner/${id}`)}
          foot={
            <div className="grid gap-2">
              <div className="px-2">
                <div className="text-xs font-medium text-muted">Businesses</div>
                <div className="text-lg font-semibold tabular-nums">{bizCount}</div>
              </div>
              <div className="px-2">
                <div className="text-xs font-medium text-muted">API keys</div>
                <div className="text-lg font-semibold tabular-nums">{keyCount}</div>
              </div>
            </div>
          }
          account={
            <div className="space-y-2">
              <div className="flex items-center gap-2.5 px-1">
                <UserButton afterSignOutUrl="/partner/sign-in" />
                <div className="min-w-0">
                  <div className="truncate text-sm font-semibold">{displayName}</div>
                  <div className="text-xs capitalize text-muted">Partner</div>
                </div>
              </div>
              <Button
                variant="ghost"
                className="w-full justify-start"
                onClick={() => (window as any).__glowClerkSignOut?.()}
              >
                Sign out
              </Button>
            </div>
          }
        />
      }
    >
      <div className="min-h-full p-5 md:p-6">
        <Routes>
          <Route index element={<HomeView />} />
          <Route path="home" element={<Navigate to="/partner/" replace />} />
          <Route path="enroll" element={<EnrollView />} />
          <Route path="biz" element={<BusinessesView />} />
          <Route path="people" element={<PeopleView />} />
          <Route path="analyze" element={<AnalyzeView />} />
          <Route path="resources" element={<ResourcesView />} />
          <Route path="settings" element={<SettingsView />} />
          <Route path="*" element={<Navigate to="/partner/" replace />} />
        </Routes>
      </div>
    </AppShell>
  );
}
