import { FormEvent, useEffect, useState } from "react";
import { Button, Card, Input, PageLede, Select } from "@augmatic/ui";
import { api } from "../../lib/api";
import { useAppAuth } from "../../lib/auth";
import { useFleet } from "../fleet-context";

export function SettingsView({
  bizName,
  onRenamed,
}: {
  bizName: string;
  onRenamed: (n: string) => void;
}) {
  const { tenant } = useFleet();
  const { signedIn, displayName } = useAppAuth();
  const [name, setName] = useState(bizName);
  const [status, setStatus] = useState("");
  const [tz, setTz] = useState(
    Intl.DateTimeFormat().resolvedOptions().timeZone || "America/New_York"
  );

  useEffect(() => setName(bizName), [bizName]);

  async function onSave(e: FormEvent) {
    e.preventDefault();
    setStatus("Saving…");
    try {
      const data = await api("/api/business", {
        method: "POST",
        body: JSON.stringify({ tenantId: tenant, name }),
      });
      onRenamed(data.business?.name || name);
      setStatus("Saved.");
    } catch (err: any) {
      setStatus(String(err.message || err));
    }
  }

  return (
    <div className="space-y-4">
      <PageLede>Business name, display time zone, export, and account.</PageLede>
      <Card>
        <h3 className="mb-2 text-base font-semibold">Business name</h3>
        <form className="flex flex-wrap gap-2" onSubmit={onSave}>
          <Input value={name} onChange={(e) => setName(e.target.value)} maxLength={120} className="max-w-md flex-1" />
          <Button type="submit">Save name</Button>
        </form>
        {status ? <p className="mt-2 text-sm text-muted">{status}</p> : null}
      </Card>
      <Card>
        <h3 className="mb-2 text-base font-semibold">Display time zone</h3>
        <Select value={tz} onChange={(e) => setTz(e.target.value)} className="max-w-md">
          <option value={tz}>{tz}</option>
          <option value="America/New_York">America/New_York</option>
          <option value="America/Chicago">America/Chicago</option>
          <option value="America/Denver">America/Denver</option>
          <option value="America/Los_Angeles">America/Los_Angeles</option>
          <option value="UTC">UTC</option>
        </Select>
      </Card>
      <Card>
        <h3 className="mb-2 text-base font-semibold">Export</h3>
        <div className="flex flex-wrap gap-2">
          <Button asChild variant="ghost">
            <a href={`/api/export.csv?tenant=${encodeURIComponent(tenant)}`}>Download CSV</a>
          </Button>
          <Button asChild variant="ghost">
            <a href="/download/GlowOpsAgent.exe">Download agent</a>
          </Button>
        </div>
      </Card>
      <Card>
        <h3 className="mb-2 text-base font-semibold">Account</h3>
        <p className="mb-3 text-sm text-muted">
          {signedIn ? `Signed in as ${displayName}` : "Not signed in."}
        </p>
        <div className="flex flex-wrap gap-2">
          {!signedIn ? (
            <Button asChild>
              <a href="/partner/sign-in">Sign in</a>
            </Button>
          ) : null}
          <Button asChild variant="ghost">
            <a href="/partner/">Partner level</a>
          </Button>
        </div>
      </Card>
    </div>
  );
}
