import { useEffect, useMemo, useState } from "react";
import { Link, Navigate, Route, Routes, useNavigate, useSearchParams } from "react-router-dom";
import { AppShell, Button, SideNav, TopBar, Wordmark } from "@augmatic/ui";
import { useAppAuth, UserButton } from "../lib/auth";
import { api } from "../lib/api";
import { FleetView } from "./views/FleetView";
import { DashboardView } from "./views/DashboardView";
import { ResourcesView } from "./views/ResourcesView";
import { PropertiesView } from "./views/PropertiesView";
import { SettingsView } from "./views/SettingsView";
import { FleetProvider } from "./fleet-context";

const NAV = [
  { id: "fleet", label: "Fleet" },
  { id: "dashboard", label: "Dashboard" },
  { id: "resources", label: "Resources" },
  { id: "properties", label: "Properties" },
  { id: "settings", label: "Settings" },
];

export function CustomerApp() {
  const { ready, signedIn, refreshToken } = useAppAuth();
  const [params] = useSearchParams();
  const nav = useNavigate();
  const tenant = (params.get("tenant") || "").trim();
  const view = (params.get("view") || "fleet").toLowerCase();
  const [bizName, setBizName] = useState("");
  const [role, setRole] = useState("");
  const [updated, setUpdated] = useState("Updated just now");

  const active = NAV.some((n) => n.id === view) ? view : "fleet";

  const qs = useMemo(() => {
    const p = new URLSearchParams(params);
    return p;
  }, [params]);

  function go(nextView: string, extra?: Record<string, string | null>) {
    const p = new URLSearchParams(qs);
    if (nextView === "fleet") p.delete("view");
    else p.set("view", nextView);
    if (extra) {
      Object.entries(extra).forEach(([k, v]) => {
        if (v == null || v === "") p.delete(k);
        else p.set(k, v);
      });
    }
    nav(`/app/?${p.toString()}`);
  }

  useEffect(() => {
    if (!ready) return;
    if (!signedIn) return;
    void (async () => {
      await refreshToken();
      if (!tenant) {
        setBizName("");
        setRole("");
        return;
      }
      try {
        const s = await api(`/api/summary?tenant=${encodeURIComponent(tenant)}`);
        setBizName(s.businessName || s.business?.name || "");
        setRole(s.myRole || s.role || "");
        setUpdated("Updated just now");
      } catch {
        setBizName("");
      }
    })();
  }, [ready, signedIn, tenant, refreshToken]);

  if (!ready) {
    return (
      <div className="grid h-dvh place-items-center bg-canvas">
        <p className="text-2xl font-semibold tracking-tight">Welcome to GLOW Ops.</p>
      </div>
    );
  }

  return (
    <FleetProvider tenant={tenant} signedIn={signedIn}>
      <AppShell
        topbar={
          <TopBar
            left={
              <>
                <Wordmark />
                <nav className="flex items-center gap-2 text-sm text-muted">
                  <Link className="text-ink-2 hover:text-ink" to="/partner/">
                    Partner level
                  </Link>
                  <span>/</span>
                  <span>Customer level</span>
                </nav>
              </>
            }
            right={
              <>
                <span className="text-xs text-muted">{updated}</span>
                <Button
                  variant="ghost"
                  size="icon"
                  aria-label="Refresh"
                  onClick={() => window.location.reload()}
                >
                  ↻
                </Button>
                {signedIn ? (
                  <UserButton afterSignOutUrl="/partner/sign-in" />
                ) : (
                  <Button asChild variant="ghost" size="sm">
                    <a href="/partner/sign-in">Sign in</a>
                  </Button>
                )}
              </>
            }
          />
        }
        sidebar={
          <SideNav
            kicker="Customer level"
            items={NAV}
            activeId={active}
            onSelect={(id) => go(id)}
            account={
              <div className="flex items-center gap-2.5 px-1">
                {signedIn ? <UserButton afterSignOutUrl="/partner/sign-in" /> : null}
                <div className="min-w-0">
                  <div className="truncate text-sm font-semibold">{bizName || "\u00A0"}</div>
                  <div className="truncate text-xs capitalize text-muted">{role || "\u00A0"}</div>
                </div>
              </div>
            }
          />
        }
      >
        <div className="h-full min-h-0 p-3.5">
          {!tenant ? (
            <div className="rounded-2xl bg-surface-2 p-8">
              <h1 className="mb-2 text-xl font-semibold tracking-tight">Open a business</h1>
              <p className="mb-4 text-sm text-muted">
                Customer level only names a business that is open. Pick one from Partner level.
              </p>
              <Button asChild>
                <a href="/partner/">Partner level</a>
              </Button>
            </div>
          ) : (
            <Routes>
              <Route
                path="*"
                element={
                  active === "dashboard" ? (
                    <DashboardView />
                  ) : active === "resources" ? (
                    <ResourcesView />
                  ) : active === "properties" ? (
                    <PropertiesView />
                  ) : active === "settings" ? (
                    <SettingsView bizName={bizName} onRenamed={setBizName} />
                  ) : (
                    <FleetView onSelectDevice={(id) => go("properties", { device: id })} />
                  )
                }
              />
            </Routes>
          )}
        </div>
      </AppShell>
    </FleetProvider>
  );
}
