import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { api } from "../lib/api";

type FleetCtx = {
  tenant: string;
  devices: any[];
  summary: any | null;
  loading: boolean;
  error: string;
  selectedId: string | null;
  setSelectedId: (id: string | null) => void;
  activeCall: string;
  setActiveCall: (c: string) => void;
  search: string;
  setSearch: (s: string) => void;
  reload: () => Promise<void>;
};

const Ctx = createContext<FleetCtx | null>(null);

export function FleetProvider({
  tenant,
  signedIn,
  children,
}: {
  tenant: string;
  signedIn: boolean;
  children: React.ReactNode;
}) {
  const [params, setParams] = useSearchParams();
  const [devices, setDevices] = useState<any[]>([]);
  const [summary, setSummary] = useState<any | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(params.get("device"));
  const [search, setSearch] = useState("");
  const activeCall = (params.get("call") || "all").toLowerCase();

  const setActiveCall = useCallback(
    (c: string) => {
      const p = new URLSearchParams(params);
      if (!c || c === "all") p.delete("call");
      else p.set("call", c);
      setParams(p, { replace: true });
    },
    [params, setParams]
  );

  const reload = useCallback(async () => {
    if (!tenant || !signedIn) {
      setDevices([]);
      setSummary(null);
      return;
    }
    setLoading(true);
    setError("");
    try {
      const [s, d] = await Promise.all([
        api(`/api/summary?tenant=${encodeURIComponent(tenant)}`),
        api(`/api/devices?tenant=${encodeURIComponent(tenant)}`),
      ]);
      setSummary(s);
      setDevices(d.devices || d || []);
    } catch (e: any) {
      setError(String(e.message || e));
      setDevices([]);
      setSummary(null);
    } finally {
      setLoading(false);
    }
  }, [tenant, signedIn]);

  useEffect(() => {
    void reload();
  }, [reload]);

  const value = useMemo(
    () => ({
      tenant,
      devices,
      summary,
      loading,
      error,
      selectedId,
      setSelectedId,
      activeCall,
      setActiveCall,
      search,
      setSearch,
      reload,
    }),
    [tenant, devices, summary, loading, error, selectedId, activeCall, setActiveCall, search, reload]
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useFleet() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useFleet outside provider");
  return ctx;
}
