import {
  ClerkProvider,
  useAuth as useClerkAuth,
  useClerk,
  useUser,
  UserButton,
} from "@clerk/clerk-react";
import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { fetchPublicConfig, setAuthToken } from "./api";

type AuthCtx = {
  ready: boolean;
  signedIn: boolean;
  publishableKey: string | null;
  displayName: string;
  refreshToken: () => Promise<void>;
};

const Ctx = createContext<AuthCtx>({
  ready: false,
  signedIn: false,
  publishableKey: null,
  displayName: "",
  refreshToken: async () => {},
});

function InnerAuth({ children }: { children: React.ReactNode }) {
  const { isLoaded, isSignedIn, getToken } = useClerkAuth();
  const { user } = useUser();
  const clerk = useClerk();

  const refreshToken = async () => {
    if (!isSignedIn) {
      setAuthToken(null);
      return;
    }
    const token = await getToken();
    setAuthToken(token);
  };

  useEffect(() => {
    void refreshToken();
  }, [isLoaded, isSignedIn]);

  const displayName =
    user?.fullName ||
    user?.primaryEmailAddress?.emailAddress?.split("@")[0] ||
    "Signed in";

  const value = useMemo(
    () => ({
      ready: isLoaded,
      signedIn: !!isSignedIn,
      publishableKey: null as string | null,
      displayName,
      refreshToken,
    }),
    [isLoaded, isSignedIn, displayName]
  );

  useEffect(() => {
    (window as any).__glowClerkSignOut = () => clerk.signOut({ redirectUrl: "/partner/sign-in" });
  }, [clerk]);

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [pk, setPk] = useState<string | null>(null);
  const [bootError, setBootError] = useState<string | null>(null);

  useEffect(() => {
    fetchPublicConfig()
      .then((cfg) => {
        const key = cfg?.clerk?.publishableKey || null;
        if (!key || !cfg?.clerk?.enabled) {
          setBootError("Sign-in is not configured on this host.");
          setPk("");
          return;
        }
        setPk(key);
      })
      .catch((e) => {
        setBootError(String(e.message || e));
        setPk("");
      });
  }, []);

  if (pk === null) {
    return (
      <div className="grid h-dvh place-items-center bg-canvas text-ink">
        <div className="text-center">
          <div className="mx-auto mb-3 h-3.5 w-3.5 rounded-full bg-accent shadow-[0_0_14px_3px_rgba(191,247,71,0.65)]" />
          <p className="text-2xl font-semibold tracking-tight">Welcome to GLOW Ops.</p>
        </div>
      </div>
    );
  }

  if (!pk) {
    return (
      <div className="grid h-dvh place-items-center bg-canvas p-6 text-ink">
        <p className="text-sm text-muted">{bootError || "Clerk is not available."}</p>
      </div>
    );
  }

  return (
    <ClerkProvider publishableKey={pk} afterSignOutUrl="/partner/sign-in">
      <InnerAuth>{children}</InnerAuth>
    </ClerkProvider>
  );
}

export function useAppAuth() {
  return useContext(Ctx);
}

export { UserButton };
