import { Navigate, Route, Routes, useLocation } from "react-router-dom";
import { PartnerApp } from "./partner/PartnerApp";
import { CustomerApp } from "./customer/CustomerApp";
import { SignInPage } from "./pages/SignInPage";
import { SignUpPage } from "./pages/SignUpPage";

export function App() {
  const loc = useLocation();

  // Legacy query-view deep links: /partner/?view=enroll → /partner/enroll
  if (loc.pathname === "/partner" || loc.pathname === "/partner/") {
    const view = new URLSearchParams(loc.search).get("view");
    if (view && view !== "home") {
      return <Navigate to={`/partner/${view}${loc.search}`} replace />;
    }
  }

  return (
    <Routes>
      <Route path="/partner/sign-in/*" element={<SignInPage />} />
      <Route path="/partner/sign-up/*" element={<SignUpPage />} />
      <Route path="/partner/*" element={<PartnerApp />} />
      <Route path="/app/*" element={<CustomerApp />} />
      <Route path="/web/*" element={<Navigate to="/partner/" replace />} />
      <Route path="*" element={<Navigate to="/partner/" replace />} />
    </Routes>
  );
}
