import { FormEvent, useEffect, useMemo, useState } from "react";
import {
  Button,
  Card,
  Input,
  PageLede,
  Select,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@augmatic/ui";
import { api } from "../../lib/api";

type Biz = {
  business_id: string;
  business_name: string;
  deviceCount?: number;
  avgGlowScore?: number | string;
  ghostCount?: number;
  lastCheckIn?: string;
  status?: { key: string; label: string };
};

export function BusinessesView() {
  const [rows, setRows] = useState<Biz[]>([]);
  const [name, setName] = useState("");
  const [q, setQ] = useState("");
  const [filter, setFilter] = useState("");
  const [sort, setSort] = useState("name");
  const [group, setGroup] = useState("");
  const [layout, setLayout] = useState<"table" | "cards">("table");
  const [status, setStatus] = useState("");

  async function load() {
    const data = await api<{ businesses: Biz[] }>("/api/partner/businesses");
    const list = data.businesses || [];
    // Enrich with summary when available via portfolio
    try {
      const p = await api<{ businesses?: any[] }>("/api/partner/portfolio");
      const map = new Map((p.businesses || []).map((b) => [b.businessId, b]));
      setRows(
        list.map((b) => {
          const s = map.get(b.business_id);
          return {
            ...b,
            deviceCount: s?.deviceCount ?? b.deviceCount ?? 0,
            avgGlowScore: s?.avgGlowScore ?? "—",
            ghostCount: s?.ghostCount ?? 0,
            lastCheckIn: s?.lastCheckIn,
            status: s?.status || { key: "none", label: "Not deployed" },
          };
        })
      );
    } catch {
      setRows(list);
    }
  }

  useEffect(() => {
    load().catch((e) => setStatus(String(e.message || e)));
  }, []);

  async function onAdd(e: FormEvent) {
    e.preventDefault();
    setStatus("Adding…");
    try {
      await api("/api/partner/businesses", {
        method: "POST",
        body: JSON.stringify({ name }),
      });
      setName("");
      setStatus("");
      await load();
    } catch (err: any) {
      setStatus(String(err.message || err));
    }
  }

  const visible = useMemo(() => {
    let list = [...rows];
    if (q.trim()) {
      const needle = q.trim().toLowerCase();
      list = list.filter((b) => (b.business_name || "").toLowerCase().includes(needle));
    }
    if (filter) list = list.filter((b) => (b.status?.key || "none") === filter);
    list.sort((a, b) => {
      if (sort === "ghosts") return (b.ghostCount || 0) - (a.ghostCount || 0);
      if (sort === "glow") return Number(a.avgGlowScore || 999) - Number(b.avgGlowScore || 999);
      if (sort === "devices") return (b.deviceCount || 0) - (a.deviceCount || 0);
      return (a.business_name || "").localeCompare(b.business_name || "");
    });
    return list;
  }, [rows, q, filter, sort]);

  const groups = useMemo(() => {
    if (group !== "status") return [{ label: "", rows: visible }];
    const order = ["none", "collecting", "ready", "stale"];
    const map = new Map<string, Biz[]>();
    for (const r of visible) {
      const k = r.status?.key || "none";
      if (!map.has(k)) map.set(k, []);
      map.get(k)!.push(r);
    }
    return order
      .filter((k) => map.has(k))
      .map((k) => ({
        label: map.get(k)![0].status?.label || k,
        rows: map.get(k)!,
      }));
  }, [visible, group]);

  return (
    <div className="space-y-4">
      <PageLede>Deploy through Intune, an RMM, or a one-click installer.</PageLede>
      {status ? <p className="text-sm text-muted">{status}</p> : null}

      <div className="flex flex-wrap items-center gap-2">
        <form className="flex gap-2" onSubmit={onAdd}>
          <Input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Business name"
            maxLength={80}
            required
            className="w-56"
          />
          <Button type="submit">Add business</Button>
        </form>
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search"
          className="max-w-xs flex-1"
        />
        <Select value={filter} onChange={(e) => setFilter(e.target.value)} className="w-40">
          <option value="">All statuses</option>
          <option value="none">Not deployed</option>
          <option value="collecting">Collecting</option>
          <option value="ready">Report ready</option>
          <option value="stale">Stale</option>
        </Select>
        <Select value={sort} onChange={(e) => setSort(e.target.value)} className="w-40">
          <option value="name">Name</option>
          <option value="ghosts">Ghosts</option>
          <option value="glow">Lowest GLOW™</option>
          <option value="devices">Devices</option>
          <option value="recent">Last check-in</option>
        </Select>
        <Select value={group} onChange={(e) => setGroup(e.target.value)} className="w-36">
          <option value="">No grouping</option>
          <option value="status">By status</option>
        </Select>
        <div className="flex gap-1">
          <Button
            type="button"
            variant={layout === "cards" ? "secondary" : "ghost"}
            size="sm"
            onClick={() => setLayout("cards")}
          >
            Cards
          </Button>
          <Button
            type="button"
            variant={layout === "table" ? "secondary" : "ghost"}
            size="sm"
            onClick={() => setLayout("table")}
          >
            Table
          </Button>
        </div>
        <span className="ml-auto text-xs text-muted">
          {visible.length} of {rows.length}
        </span>
      </div>

      {layout === "table" ? (
        <Card className="p-0 overflow-hidden">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Business</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Devices</TableHead>
                <TableHead>
                  GLOW<sup className="glow-tm">™</sup>
                </TableHead>
                <TableHead>Ghosts</TableHead>
                <TableHead>Last check-in</TableHead>
                <TableHead>Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {groups.flatMap((g) => {
                const head = g.label
                  ? [
                      <TableRow key={`g-${g.label}`}>
                        <TableCell colSpan={7} className="bg-wash text-xs font-semibold text-muted">
                          {g.label} · {g.rows.length}
                        </TableCell>
                      </TableRow>,
                    ]
                  : [];
                const body = g.rows.map((r) => {
                  const href = `/app/?from=partner&tenant=${encodeURIComponent(r.business_id)}&view=fleet`;
                  return (
                    <TableRow key={r.business_id}>
                      <TableCell className="font-semibold">{r.business_name}</TableCell>
                      <TableCell>{r.status?.label || "—"}</TableCell>
                      <TableCell className="tabular-nums">{r.deviceCount ?? 0}</TableCell>
                      <TableCell className="tabular-nums">{r.avgGlowScore ?? "—"}</TableCell>
                      <TableCell className="tabular-nums">{r.ghostCount ?? 0}</TableCell>
                      <TableCell>{r.lastCheckIn || "—"}</TableCell>
                      <TableCell>
                        <div className="flex flex-wrap gap-1">
                          <Button asChild variant="ghost" size="sm">
                            <a href={href}>Open</a>
                          </Button>
                          <Button variant="ghost" size="sm">
                            Print PDF
                          </Button>
                          <Button variant="ghost" size="sm">
                            Send
                          </Button>
                          <Button size="sm">Deploy</Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                });
                return [...head, ...body];
              })}
            </TableBody>
          </Table>
        </Card>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {visible.map((r) => {
            const href = `/app/?from=partner&tenant=${encodeURIComponent(r.business_id)}&view=fleet`;
            return (
              <Card key={r.business_id}>
                <div className="mb-2 text-base font-semibold">{r.business_name}</div>
                <div className="mb-3 text-xs text-muted">{r.status?.label || "—"}</div>
                <div className="mb-4 grid grid-cols-2 gap-2 text-sm">
                  <div>
                    <div className="text-xs text-muted">Devices</div>
                    <div className="font-semibold tabular-nums">{r.deviceCount ?? 0}</div>
                  </div>
                  <div>
                    <div className="text-xs text-muted">
                      GLOW<sup className="glow-tm">™</sup>
                    </div>
                    <div className="font-semibold tabular-nums">{r.avgGlowScore ?? "—"}</div>
                  </div>
                </div>
                <Button asChild className="w-full">
                  <a href={href}>Open</a>
                </Button>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}
