import { Card, CallPill, KpiStrip, PageLede } from "@augmatic/ui";
import { useFleet } from "../fleet-context";

const CALLS = ["keep", "repair", "redeploy", "refresh", "recycle", "ghost"];

export function DashboardView() {
  const { devices, summary } = useFleet();
  const by = summary?.byCall || {};
  const total = Math.max(1, summary?.deviceCount || devices.length || 1);

  return (
    <div className="space-y-4">
      <h1 className="text-xl font-semibold tracking-tight">Dashboard</h1>
      <PageLede>Call mix and devices for this fleet.</PageLede>
      <Card>
        <KpiStrip
          columns={6}
          items={[
            { label: "Devices", value: summary?.deviceCount ?? 0 },
            {
              label: (
                <span>
                  Avg GLOW<sup className="glow-tm">™</sup>
                </span>
              ),
              value: summary?.avgGlowScore ?? "—",
            },
            { label: "Ghosts", value: summary?.ghostCount ?? 0 },
            { label: "Repair", value: summary?.repairBeforeReplaceCount ?? 0 },
            { label: "Mfg kg", value: summary?.manufacturingKgOnBooks ?? 0 },
            { label: "Avoid", value: summary?.avoidablePurchasesIfExtended ?? 0 },
          ]}
        />
      </Card>
      <div className="grid gap-4 lg:grid-cols-2">
        <Card>
          <h3 className="mb-4 text-base font-semibold">Call mix</h3>
          <div className="space-y-2.5">
            {CALLS.map((c) => {
              const n = by[c] || 0;
              const pct = Math.round((100 * n) / total);
              const label = c.charAt(0).toUpperCase() + c.slice(1);
              return (
                <div key={c} className="grid grid-cols-[5.5rem_1fr_2rem] items-center gap-2 text-xs">
                  <span className="font-semibold">{label}</span>
                  <div className="h-2 overflow-hidden rounded-full bg-surface">
                    <i className="block h-full rounded-full bg-ink" style={{ width: `${pct}%` }} />
                  </div>
                  <b className="text-right tabular-nums">{n}</b>
                </div>
              );
            })}
          </div>
        </Card>
        <Card>
          <h3 className="mb-4 text-base font-semibold">Devices</h3>
          <ul className="space-y-2">
            {[...devices]
              .sort((a, b) => (a.glow_score ?? 999) - (b.glow_score ?? 999))
              .map((d) => (
                <li
                  key={d.id}
                  className="flex items-center justify-between gap-3 rounded-lg bg-surface px-3 py-2"
                >
                  <strong className="truncate text-sm">{d.device_name || d.id}</strong>
                  <div className="flex items-center gap-2">
                    <CallPill call={d.call_label || d.call} />
                    <em className="not-italic font-semibold tabular-nums">{d.glow_score ?? "—"}</em>
                  </div>
                </li>
              ))}
            {!devices.length ? <li className="text-sm text-muted">No devices yet</li> : null}
          </ul>
        </Card>
      </div>
    </div>
  );
}
