import { cn } from "../lib/utils";

export type SideNavItem = {
  id: string;
  label: string;
};

export function SideNav({
  brand,
  kicker,
  items,
  activeId,
  onSelect,
  foot,
  account,
  className,
}: {
  brand?: React.ReactNode;
  kicker?: string;
  items: SideNavItem[];
  activeId: string;
  onSelect: (id: string) => void;
  foot?: React.ReactNode;
  account?: React.ReactNode;
  className?: string;
}) {
  return (
    <aside
      className={cn(
        "flex h-full min-h-0 w-[13.5rem] flex-col gap-0.5 overflow-auto border-r border-line bg-gradient-to-b from-[#e9eee3] to-wash px-3.5 py-4",
        className
      )}
    >
      {brand ? <div className="mb-3 border-b border-line px-2 pb-3">{brand}</div> : null}
      {kicker ? (
        <p className="mb-2 px-2 text-xs font-medium text-muted">{kicker}</p>
      ) : null}
      <nav className="flex flex-col gap-0.5">
        {items.map((item) => {
          const active = item.id === activeId;
          return (
            <button
              key={item.id}
              type="button"
              onClick={() => onSelect(item.id)}
              className={cn(
                "w-full rounded-lg px-3 py-2.5 text-left text-[0.9rem] font-semibold tracking-tight transition-colors",
                active
                  ? "bg-surface text-ink shadow-[var(--shadow-soft),inset_3px_0_0_var(--color-accent)]"
                  : "bg-transparent text-ink-2 hover:bg-white/55 hover:text-ink"
              )}
            >
              {item.label}
            </button>
          );
        })}
      </nav>
      {foot ? (
        <div className="mt-auto space-y-2 border-t border-line px-1 pt-3">{foot}</div>
      ) : null}
      {account ? (
        <div className={cn("border-t border-line px-1 pt-3", foot ? "mt-2" : "mt-auto")}>
          {account}
        </div>
      ) : null}
    </aside>
  );
}
