import { FormEvent, useEffect, useState } from "react";
import { Button, Card, Input, PageLede, Select, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@augmatic/ui";
import { api } from "../../lib/api";

type Biz = { business_id: string; business_name: string };
type KeyRow = {
  label?: string;
  business_name?: string;
  key_prefix?: string;
  status?: string;
  expires_at?: string;
  use_count?: number;
};

export function EnrollView() {
  const [biz, setBiz] = useState<Biz[]>([]);
  const [businessId, setBusinessId] = useState("");
  const [ttl, setTtl] = useState("24");
  const [label, setLabel] = useState("");
  const [fresh, setFresh] = useState<{ url: string; key: string; password: string; exp: string } | null>(null);
  const [rows, setRows] = useState<KeyRow[]>([]);
  const [status, setStatus] = useState("");

  async function load() {
    const b = await api<{ businesses: Biz[] }>("/api/partner/businesses");
    const list = b.businesses || [];
    setBiz(list);
    if (!businessId && list[0]) setBusinessId(list[0].business_id);
    const keys = await api<{ keys?: KeyRow[] }>("/api/partner/enrollment-keys");
    setRows(keys.keys || (keys as any) || []);
  }

  useEffect(() => {
    load().catch((e) => setStatus(String(e.message || e)));
  }, []);

  async function onMint(e: FormEvent) {
    e.preventDefault();
    setStatus("Minting…");
    try {
      const data = await api("/api/partner/enrollment-keys", {
        method: "POST",
        body: JSON.stringify({
          businessId,
          ttlHours: Number(ttl),
          label: label || undefined,
        }),
      });
      setFresh({
        url: data.dashboardUrl || "https://getglowop.com",
        key: data.key || data.joinKey,
        password: data.password || data.joinPassword,
        exp: data.expiresAt || data.expires_at || "",
      });
      setStatus("");
      await load();
    } catch (err: any) {
      setStatus(String(err.message || err));
    }
  }

  function copyAll() {
    if (!fresh) return;
    void navigator.clipboard.writeText(
      `URL: ${fresh.url}\nKey: ${fresh.key}\nPassword: ${fresh.password}\nExpires: ${fresh.exp}`
    );
  }

  return (
    <div className="space-y-5">
      <PageLede>
        Pick a business, mint a join key, then paste the URL, key, and password into the agent.
      </PageLede>

      <Card className="max-w-xl">
        <form className="grid gap-3 sm:grid-cols-2" onSubmit={onMint}>
          <label className="grid gap-1.5 text-xs font-semibold text-ink-2">
            Business
            <Select value={businessId} onChange={(e) => setBusinessId(e.target.value)} required>
              {biz.map((b) => (
                <option key={b.business_id} value={b.business_id}>
                  {b.business_name}
                </option>
              ))}
            </Select>
          </label>
          <label className="grid gap-1.5 text-xs font-semibold text-ink-2">
            Expires
            <Select value={ttl} onChange={(e) => setTtl(e.target.value)}>
              <option value="1">1 hour</option>
              <option value="24">24 hours</option>
              <option value="168">7 days</option>
              <option value="720">30 days</option>
            </Select>
          </label>
          <label className="grid gap-1.5 text-xs font-semibold text-ink-2 sm:col-span-2">
            Label
            <Input value={label} onChange={(e) => setLabel(e.target.value)} placeholder="e.g. Front desk PC" maxLength={64} />
          </label>
          <div className="sm:col-span-2">
            <Button type="submit">Mint join key</Button>
          </div>
        </form>

        {fresh ? (
          <div className="mt-5 space-y-2 border-t border-line pt-4">
            {[
              ["URL", fresh.url],
              ["Key", fresh.key],
              ["Password", fresh.password],
            ].map(([k, v]) => (
              <div key={k} className="grid grid-cols-[5rem_1fr] gap-2 text-sm">
                <span className="text-xs uppercase tracking-wide text-muted">{k}</span>
                <code className="overflow-hidden text-ellipsis rounded-md bg-surface px-2 py-1 font-mono text-xs">
                  {v}
                </code>
              </div>
            ))}
            <div className="flex items-center justify-between gap-2 pt-1">
              <p className="text-xs text-muted">{fresh.exp ? `Expires ${fresh.exp}` : "Password shown once."}</p>
              <Button variant="ghost" size="sm" type="button" onClick={copyAll}>
                Copy all
              </Button>
            </div>
          </div>
        ) : null}
        {status ? <p className="mt-3 text-sm text-muted">{status}</p> : null}
      </Card>

      <Card>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Label</TableHead>
              <TableHead>Business</TableHead>
              <TableHead>Key</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Expires</TableHead>
              <TableHead>Uses</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {(Array.isArray(rows) ? rows : []).map((r, i) => (
              <TableRow key={i}>
                <TableCell>{r.label || "—"}</TableCell>
                <TableCell>{r.business_name || "—"}</TableCell>
                <TableCell className="font-mono text-xs">{r.key_prefix || "—"}</TableCell>
                <TableCell>{r.status || "—"}</TableCell>
                <TableCell>{r.expires_at || "—"}</TableCell>
                <TableCell>{r.use_count ?? "—"}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Card>
    </div>
  );
}
