import { useEffect, useState } from "react";
import { Button, Card, CardHeader, CardTitle, KpiStrip } from "@augmatic/ui";
import { api } from "../../lib/api";

type Portfolio = {
  businessCount?: number;
  deviceCount?: number;
  avgGlowScore?: number | string;
  ghostCount?: number;
  repairCount?: number;
  manufacturingKgOnBooks?: number;
  byCall?: Record<string, number>;
  businesses?: Array<{
    businessId: string;
    businessName: string;
    deviceCount: number;
    avgGlowScore?: number | string;
    ghostCount: number;
  }>;
};

const CALLS = ["keep", "repair", "redeploy", "refresh", "recycle", "ghost"];

export function HomeView() {
  const [p, setP] = useState<Portfolio | null>(null);
  const [err, setErr] = useState("");

  useEffect(() => {
    api<Portfolio>("/api/partner/portfolio")
      .then(setP)
      .catch((e) => setErr(String(e.message || e)));
  }, []);

  const total = Math.max(1, p?.deviceCount || 1);
  const by = p?.byCall || {};

  return (
    <div className="space-y-6">
      <KpiStrip
        items={[
          { label: "Businesses", value: p?.businessCount ?? "…" },
          { label: "Devices", value: p?.deviceCount ?? "…" },
          {
            label: (
              <span>
                Avg GLOW<sup className="glow-tm">™</sup>
              </span>
            ),
            value: p?.avgGlowScore ?? "…",
          },
          { label: "Ghosts", value: p?.ghostCount ?? "…" },
          { label: "Repair", value: p?.repairCount ?? "…" },
          { label: "Mfg kg", value: p?.manufacturingKgOnBooks ?? "…" },
        ]}
      />

      <div className="grid gap-4 lg:grid-cols-[1fr_1.15fr]">
        <Card>
          <CardHeader>
            <CardTitle>Calls across portfolio</CardTitle>
          </CardHeader>
          <div className="space-y-2.5">
            {CALLS.map((c) => {
              const n = by[c] || 0;
              const pct = Math.round((100 * n) / total);
              const label = c.charAt(0).toUpperCase() + c.slice(1);
              return (
                <div key={c} className="grid grid-cols-[5.5rem_1fr_2rem] items-center gap-2 text-xs">
                  <span className="font-semibold text-ink">{label}</span>
                  <div className="h-2 overflow-hidden rounded-full bg-surface">
                    <i className="block h-full rounded-full bg-ink" style={{ width: `${pct}%` }} />
                  </div>
                  <b className="text-right tabular-nums">{n}</b>
                </div>
              );
            })}
          </div>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Businesses</CardTitle>
            <div className="flex gap-2">
              <Button variant="ghost" size="sm" onClick={() => window.print()}>
                Print PDF
              </Button>
              <Button variant="ghost" size="sm">
                Send
              </Button>
            </div>
          </CardHeader>
          {err ? <p className="text-sm text-red">{err}</p> : null}
          <ul className="space-y-2">
            {(p?.businesses || []).length === 0 && !err ? (
              <li className="text-sm text-muted">No businesses yet — add one under Businesses.</li>
            ) : (
              (p?.businesses || []).map((b) => (
                <li key={b.businessId}>
                  <a
                    className="block rounded-lg bg-surface px-3.5 py-3 transition hover:-translate-y-px hover:bg-[#fbfff0]"
                    href={`/app/?from=partner&tenant=${encodeURIComponent(b.businessId)}&view=fleet`}
                  >
                    <div className="font-semibold tracking-tight">{b.businessName || "Business"}</div>
                    <div className="text-xs text-muted">
                      {b.deviceCount} devices · GLOW<sup className="glow-tm">™</sup>{" "}
                      {b.avgGlowScore ?? "—"} · ghosts {b.ghostCount}
                    </div>
                  </a>
                </li>
              ))
            )}
          </ul>
        </Card>
      </div>
    </div>
  );
}
