import { FormEvent, useEffect, useState } from "react";
import { Button, Card, CardHeader, CardTitle, Input, PageLede, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@augmatic/ui";
import { api } from "../../lib/api";

export function SettingsView() {
  const [keys, setKeys] = useState<any[]>([]);
  const [label, setLabel] = useState("");
  const [fresh, setFresh] = useState("");
  const [mcpUrl, setMcpUrl] = useState("/mcp");
  const [config, setConfig] = useState("");
  const [status, setStatus] = useState("");

  async function load() {
    const data = await api("/api/partner/mcp-keys");
    setKeys(data.keys || []);
    if (data.mcpUrl) setMcpUrl(data.mcpUrl);
    setConfig(
      data.config ||
        JSON.stringify(
          {
            mcpServers: {
              glowops: {
                url: data.mcpUrl || `${location.origin}/mcp`,
                headers: { Authorization: "Bearer <key>" },
              },
            },
          },
          null,
          2
        )
    );
  }

  useEffect(() => {
    load().catch((e) => setStatus(String(e.message || e)));
  }, []);

  async function onMint(e: FormEvent) {
    e.preventDefault();
    setStatus("Minting…");
    try {
      const data = await api("/api/partner/mcp-keys", {
        method: "POST",
        body: JSON.stringify({ label: label || "MCP key" }),
      });
      setFresh(data.key || data.token || "");
      setLabel("");
      setStatus("");
      await load();
    } catch (err: any) {
      setStatus(String(err.message || err));
    }
  }

  return (
    <div className="space-y-4">
      <PageLede>Optional access for a partner AI agent.</PageLede>
      <Card>
        <CardHeader>
          <CardTitle>MCP</CardTitle>
        </CardHeader>
        <p className="mb-3 text-sm text-muted">
          Mint a key when a partner AI agent needs read access to fleet data.
        </p>
        {fresh ? (
          <div className="mb-3 flex items-center gap-2 rounded-lg bg-[#f3ffe0] px-3 py-2">
            <code className="flex-1 overflow-hidden text-ellipsis font-mono text-xs">{fresh}</code>
            <Button
              variant="ghost"
              size="sm"
              type="button"
              onClick={() => void navigator.clipboard.writeText(fresh)}
            >
              Copy
            </Button>
          </div>
        ) : null}
        <p className="mb-2 text-xs text-muted">Endpoint · {mcpUrl}</p>
        <pre className="mb-4 overflow-auto rounded-lg bg-surface p-3 font-mono text-xs">{config}</pre>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Label</TableHead>
              <TableHead>Prefix</TableHead>
              <TableHead>Scopes</TableHead>
              <TableHead>Created</TableHead>
              <TableHead>Used</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {keys.map((k, i) => (
              <TableRow key={i}>
                <TableCell>{k.label || "—"}</TableCell>
                <TableCell className="font-mono text-xs">{k.prefix || k.key_prefix || "—"}</TableCell>
                <TableCell>{(k.scopes || []).join(", ") || "read"}</TableCell>
                <TableCell>{k.created_at || k.created || "—"}</TableCell>
                <TableCell>{k.last_used_at || k.used || "—"}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
        <form className="mt-4 flex gap-2" onSubmit={onMint}>
          <Input
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            placeholder="Key label"
            maxLength={64}
            className="max-w-xs"
          />
          <Button type="submit">Mint key</Button>
        </form>
        {status ? <p className="mt-2 text-sm text-muted">{status}</p> : null}
      </Card>
    </div>
  );
}
