import { cn } from "../lib/utils";

export type KpiItem = {
  label: React.ReactNode;
  value: React.ReactNode;
};

export function KpiStrip({
  items,
  className,
  columns = 6,
}: {
  items: KpiItem[];
  className?: string;
  columns?: number;
}) {
  return (
    <div
      className={cn("grid gap-3", className)}
      style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}
    >
      {items.map((item, i) => (
        <div
          key={i}
          className="flex min-h-[5.25rem] flex-col justify-between gap-2 rounded-xl bg-surface-2 px-4 py-3.5"
        >
          <div className="text-xs font-medium text-muted">{item.label}</div>
          <div className="text-2xl font-semibold tracking-tight tabular-nums text-ink">
            {item.value}
          </div>
        </div>
      ))}
    </div>
  );
}
