import { FormEvent, useEffect, useState } from "react";
import { Button, Card, CardHeader, CardTitle, Input, PageLede, Select } from "@augmatic/ui";
import { api } from "../../lib/api";

export function PeopleView() {
  const [biz, setBiz] = useState<any[]>([]);
  const [businessId, setBusinessId] = useState("");
  const [roleHint, setRoleHint] = useState("Your role: —");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("admin");
  const [members, setMembers] = useState<any[]>([]);
  const [invites, setInvites] = useState<any[]>([]);
  const [catalog, setCatalog] = useState<any[]>([]);
  const [status, setStatus] = useState("");

  async function load(bid: string) {
    if (!bid) return;
    const mem = await api(`/api/partner/members?businessId=${encodeURIComponent(bid)}`);
    setMembers(mem.members || []);
    setRoleHint(`Your role: ${mem.myRole || "—"}`);
    const inv = await api(`/api/partner/invitations?businessId=${encodeURIComponent(bid)}`);
    setInvites(inv.invitations || inv.invites || []);
  }

  useEffect(() => {
    (async () => {
      const b = await api("/api/partner/businesses");
      const list = b.businesses || [];
      setBiz(list);
      const first = list[0]?.business_id || "";
      setBusinessId(first);
      const cat = await api("/api/partner/rbac/catalog");
      setCatalog(cat.permissions || cat.catalog || []);
      if (first) await load(first);
    })().catch((e) => setStatus(String(e.message || e)));
  }, []);

  useEffect(() => {
    if (businessId) load(businessId).catch((e) => setStatus(String(e.message || e)));
  }, [businessId]);

  async function onInvite(e: FormEvent) {
    e.preventDefault();
    setStatus("Sending…");
    try {
      await api("/api/partner/invitations", {
        method: "POST",
        body: JSON.stringify({ businessId, email, role }),
      });
      setEmail("");
      setStatus("Invite sent.");
      await load(businessId);
    } catch (err: any) {
      setStatus(String(err.message || err));
    }
  }

  return (
    <div className="space-y-4">
      <PageLede>Invite people and set roles.</PageLede>
      <div className="flex flex-wrap items-end gap-4 rounded-xl bg-surface-2 p-4">
        <label className="grid gap-1.5 text-xs font-semibold">
          Business
          <Select value={businessId} onChange={(e) => setBusinessId(e.target.value)} className="w-64">
            {biz.map((b) => (
              <option key={b.business_id} value={b.business_id}>
                {b.business_name}
              </option>
            ))}
          </Select>
        </label>
        <span className="pb-2 text-sm text-muted">{roleHint}</span>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Invite</CardTitle>
        </CardHeader>
        <form className="flex flex-wrap gap-2" onSubmit={onInvite}>
          <Input
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="user@company.com"
            className="min-w-[16rem] flex-1"
          />
          <Select value={role} onChange={(e) => setRole(e.target.value)} className="w-36">
            <option value="viewer">Viewer</option>
            <option value="operator">Operator</option>
            <option value="admin">Admin</option>
          </Select>
          <Button type="submit">Send invite</Button>
        </form>
        {status ? <p className="mt-2 text-sm text-muted">{status}</p> : null}
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Members</CardTitle>
        </CardHeader>
        <ul className="space-y-2">
          {members.length === 0 ? (
            <li className="text-sm text-muted">No members yet.</li>
          ) : (
            members.map((m, i) => (
              <li key={i} className="rounded-lg bg-surface px-3 py-2 text-sm">
                <div className="font-medium">{m.email || m.name || "Member"}</div>
                <div className="text-xs capitalize text-muted">{m.role}</div>
              </li>
            ))
          )}
        </ul>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Pending invites</CardTitle>
        </CardHeader>
        <ul className="space-y-2">
          {invites.length === 0 ? (
            <li className="text-sm text-muted">No pending invites.</li>
          ) : (
            invites.map((inv, i) => (
              <li key={i} className="rounded-lg bg-surface px-3 py-2 text-sm">
                {inv.email} · {inv.role}
              </li>
            ))
          )}
        </ul>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Permission matrix</CardTitle>
        </CardHeader>
        <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
          {(Array.isArray(catalog) ? catalog : []).map((p: any, i: number) => (
            <div key={i} className="rounded-lg bg-surface px-3 py-2">
              <div className="font-mono text-xs font-medium">{p.id || p.key || p.name}</div>
              <div className="text-xs text-muted">{p.description || p.label || ""}</div>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}
