import { SignIn } from "@clerk/clerk-react";
import { Wordmark } from "@augmatic/ui";

export function SignInPage() {
  const next = new URLSearchParams(location.search).get("next") || "/partner/";
  const force = next.startsWith("/partner") || next.startsWith("/app") ? next : "/partner/";
  return (
    <div className="grid min-h-dvh place-items-center bg-canvas p-6">
      <div className="w-full max-w-md rounded-2xl bg-surface p-6 shadow-[var(--shadow-soft)]">
        <div className="mb-4">
          <Wordmark />
          <p className="mt-2 text-xs font-medium text-muted">Partner level · Sign in</p>
        </div>
        <SignIn routing="path" path="/partner/sign-in" forceRedirectUrl={force} />
      </div>
    </div>
  );
}
